                    </PressableWithoutFeedback>
                )}
                {shouldDisplaySearchRouter && <SearchButton />}
                {displaySearch && (
                    <Tooltip text={translate('common.find')}>
                        <PressableWithoutFeedback
                            accessibilityLabel={translate('sidebarScreen.buttonFind')}
